  if (!auth.session?.authenticated)
    return (
      <Navigate
        to={`/login?returnTo=${encodeURIComponent(location.pathname + location.search)}`}
        replace
      />
    );
  if (roles && !hasAnyRole(auth.session.user?.roles, roles))
    return (
      <div className="page">
        <ForbiddenState />
      </div>
    );
  return (
    <AppShell admin={admin}>
      <Outlet />
    </AppShell>
